Общий контракт: solve(data); вход не менять. Если условие не задаёт иное, числовые входные значения — целые int, не bool. Логические значения и произвольные JSON-значения допустимы в полях, для которых это прямо указано. Идентификаторы, названия товаров и навыков — строки; строки сравниваются лексикографически с учётом регистра. Результат должен быть детерминированным JSON-значением. Типы сравниваются точно: bool, int и float различаются. Порядок ключей словаря не важен; порядок списка важен. Неописанные входы вне области задачи.", "entrypoint": "solve(data)"}, "visible_cases": [{"id": "C01", "input": {}, "expected": {}}, {"id": "C02", "input": {"a": []}, "expected": {"a": []}}, {"id": "C03", "input": {"a": [], "b": ["a"]}, "expected": {"a": [], "b": ["a"]}}, {"id": "C04", "input": {"a": [], "b": ["a"], "c": ["a", "b"]}, "expected": {"a": [], "b": ["a"], "c": ["b"]}}, {"id": "C05", "input": {"a": [], "b": [], "c": ["b", "a"]}, "expected": {"a": [], "b": [], "c": ["a", "b"]}}, {"id": "C06", "input": {"a": [], "b": ["a", "a"]}, "expected": {"a": [], "b": ["a"]}}, {"id": "C07", "input": {"a": [], "b": ["a"], "c": ["b"], "d": ["a", "c"]}, "expected": {"a": [], "b": ["a"], "c": ["b"], "d": ["c"]}}, {"id": "C08", "input": {"a": [], "b": ["a"], "c": ["a"], "d": ["a", "b", "c"]}, "expected": {"a": [], "b": ["a"], "c": ["a"], "d": ["b", "c"]}}, {"id": "C09", "input": {"z": [], "a": ["z"], "b": ["z", "a"]}, "expected": {"z": [], "a": ["z"], "b": ["a"]}}, {"id": "C10", "input": {"a": [], "b": []}, "expected": {"a": [], "b": []}}], "code": "def solve(data):
    def reaches(start,target):
        stack = [start]
        seen = set()
        while stack:
            node = stack.pop()
            if node == target:
                return True
            if node not in seen:
                seen.add(node)
                stack.extend(data[node])
        return False
    out = {}
    for node,parents in data.items():
        unique = sorted(set(parents))
        out[node] = [p for p in unique if not any(reaches(p,q) for q in unique)]
    return out
